import React from 'react';
import { Link } from 'react-router-dom';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const RelatedOpportunities = ({ opportunities }) => {
  const getDeadlineBadgeClass = (daysLeft) => {
    if (daysLeft === null) return 'deadline-badge safe';
    if (daysLeft <= 0) return 'deadline-badge expired bg-gray-500/20 text-gray-500 border-gray-500/20';
    if (daysLeft <= 7) return 'deadline-badge urgent';
    if (daysLeft <= 14) return 'deadline-badge warning';
    return 'deadline-badge safe';
  };

  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-brand-purple/10 flex items-center justify-center">
            <Icon name="Sparkles" size={20} className="text-brand-purple" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-bold text-primary">Related Opportunities</h2>
            <p className="text-xs md:text-sm text-muted-foreground mt-1">
              Similar opportunities you might like
            </p>
          </div>
        </div>
        <Link to="/opportunity-discovery">
          <Button variant="ghost" size="sm" iconName="ArrowRight" iconPosition="right">
            View All
          </Button>
        </Link>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
        {opportunities?.map((opp) => {
          const daysLeft = opp?.daysLeft;
          const isExpired = daysLeft !== null && daysLeft <= 0;

          return (
            <Link
              key={opp?.id}
              to={`/opportunity-detail/${opp?.id}`}
              className="opportunity-card group"
            >
              <div className="relative rounded-xl overflow-hidden mb-4 aspect-[16/9]">
                <Image
                  src={opp?.image}
                  alt={opp?.imageAlt}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                />
                <div className="absolute top-3 right-3">
                  <span className={getDeadlineBadgeClass(daysLeft)}>
                    <Icon name={isExpired ? "AlertCircle" : "Clock"} size={12} />
                    {isExpired ? "Expired" : (daysLeft === null ? "Open" : `${daysLeft}d`)}
                  </span>
                </div>
                {opp?.verified && (
                  <div className="absolute top-3 left-3">
                    <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-success text-success-foreground">
                      <Icon name="ShieldCheck" size={12} />
                    </span>
                  </div>
                )}
              </div>
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-muted text-muted-foreground">
                    <Icon name="Tag" size={12} />
                    {opp?.category}
                  </span>
                </div>

                <h3 className="text-base md:text-lg font-semibold text-primary line-clamp-2 group-hover:text-secondary transition-colors duration-300">
                  {opp?.title}
                </h3>

                <div className="flex items-center gap-2 text-xs md:text-sm text-muted-foreground">
                  <Icon name="Building2" size={14} />
                  <span className="truncate">{opp?.organization}</span>
                </div>

                <div className="flex items-center gap-2 text-xs md:text-sm text-muted-foreground">
                  <Icon name="MapPin" size={14} />
                  <span className="truncate">{opp?.location}</span>
                </div>

                <div className="flex items-center justify-between pt-3 border-t border-border">
                  <div className="flex items-center gap-2">
                    <Icon name="Users" size={14} className="text-secondary" />
                    <span className="text-xs text-muted-foreground">{opp?.applicants}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Icon name="TrendingUp" size={14} className="text-success" />
                    <span className="text-xs text-muted-foreground">{opp?.successRate}%</span>
                  </div>
                </div>
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
};

export default RelatedOpportunities;