import React from 'react';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const StickyActionBar = ({ opportunity, onSave, onShare, onApply, isSaved, isVisible }) => {
  if (!isVisible) return null;

  const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;
  const daysLeft = opportunity?.daysLeft;

  return (
    <div className={cn(
      "fixed bottom-0 left-0 right-0 z-30 bg-card border-t-2 border-border shadow-elevated transition-all duration-300",
      isExpired && "opacity-95"
    )}>
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-3 md:py-4">
        <div className="flex items-center justify-between gap-2 md:gap-4">
          <div className="flex-1 min-w-0">
            <h3 className={cn(
              "text-sm md:text-base font-semibold truncate",
              isExpired ? "text-gray-500" : "text-primary"
            )}>
              {opportunity?.title}
            </h3>
            <div className="flex items-center gap-1 md:gap-3 mt-1">
              <span className="text-xs md:text-sm text-muted-foreground truncate">
                {opportunity?.organization}
              </span>
              <span className={cn(
                "text-xs font-medium whitespace-nowrap",
                isExpired ? "text-red-500" : "text-muted-foreground"
              )}>
                • {isExpired ? "Expired" : (daysLeft === null ? (opportunity?.deadline || "No Deadline") : `${daysLeft}d left`)}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1 md:gap-3 flex-shrink-0">
            <Button
              variant="outline"
              size="sm"
              iconName={isSaved ? "BookmarkCheck" : "Bookmark"}
              onClick={isExpired ? null : onSave}
              disabled={isExpired}
              className={cn("hidden sm:inline-flex", isExpired && "opacity-50 grayscale cursor-not-allowed")}
              title={isExpired ? "Cannot save expired opportunity" : (isSaved ? "Saved" : "Save")}
            >
              {isSaved ? 'Saved' : 'Save'}
            </Button>
            <Button
              variant="outline"
              size="sm"
              iconName="Share2"
              onClick={isExpired ? null : onShare}
              disabled={isExpired}
              className={cn("hidden sm:inline-flex", isExpired && "opacity-50 grayscale cursor-not-allowed")}
              title={isExpired ? "Cannot share expired opportunity" : "Share"}
            >
              Share
            </Button>
            <Button
              variant="outline"
              size="icon"
              iconName={isSaved ? "BookmarkCheck" : "Bookmark"}
              onClick={isExpired ? null : onSave}
              disabled={isExpired}
              className={cn("sm:hidden", isExpired && "opacity-50 grayscale cursor-not-allowed")}
              title={isExpired ? "Cannot save expired opportunity" : (isSaved ? "Saved" : "Save")}
            />
            <Button
              variant="outline"
              size="icon"
              iconName="Share2"
              onClick={isExpired ? null : onShare}
              disabled={isExpired}
              className={cn("sm:hidden", isExpired && "opacity-50 grayscale cursor-not-allowed")}
              title={isExpired ? "Cannot share expired opportunity" : "Share"}
            />
            <Button
              variant={isExpired ? "outline" : "default"}
              size="default"
              iconName={isExpired ? "Lock" : "ExternalLink"}
              iconPosition="right"
              onClick={isExpired ? null : onApply}
              disabled={isExpired}
              className={cn(
                "px-4 md:px-8 text-xs md:text-sm h-9 md:h-10",
                isExpired && "opacity-50 grayscale cursor-not-allowed"
              )}
            >
              {isExpired ? 'Expired' : 'Apply Now'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StickyActionBar;
