import React from 'react';
import Icon from '../../../components/AppIcon';

const KeyInformation = ({ opportunity }) => {
  const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;

  const infoItems = [
    {
      icon: 'Calendar',
      label: 'Application Deadline',
      value: opportunity?.daysLeft === null 
        ? (opportunity?.deadline || 'Rolling/Open')
        : new Date(opportunity.deadline).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
          }),
      highlight: true
    },
    {
      icon: 'Clock',
      label: 'Duration',
      value: opportunity?.duration
    },
    {
      icon: 'GraduationCap',
      label: 'Education Level',
      value: opportunity?.educationLevel
    },
    {
      icon: 'Globe',
      label: 'Eligibility',
      value: opportunity?.eligibility
    },
    {
      icon: 'Award',
      label: 'Type',
      value: opportunity?.type
    },
    {
      icon: 'Languages',
      label: 'Language',
      value: opportunity?.language
    }
  ];

  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-primary/10 flex items-center justify-center">
          <Icon name="Info" size={20} className="text-primary" />
        </div>
        <h2 className="text-xl md:text-2xl font-bold text-primary">Key Information</h2>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-4 md:gap-6">
        {infoItems?.map((item, index) => (
          <div
            key={index}
            className={`p-4 md:p-5 rounded-xl border-2 transition-all duration-300 ${item?.highlight
                ? 'border-accent bg-accent/5' : 'border-border bg-background hover:border-secondary/50'
              }`}
          >
            <div className="flex items-start gap-3">
              <div
                className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${item?.highlight ? 'bg-accent text-accent-foreground' : 'bg-muted text-muted-foreground'
                  }`}
              >
                <Icon name={item?.icon} size={18} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs md:text-sm text-muted-foreground mb-1">{item?.label}</p>
                <p className="text-sm md:text-base font-semibold text-foreground">
                  {item?.value}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
      <div className={`mt-6 p-4 md:p-5 rounded-xl border-2 ${isExpired ? 'bg-gray-500/10 border-gray-500/20' : 'bg-success/10 border-success/20'}`}>
        <div className="flex items-start gap-3">
          <Icon name={isExpired ? "XCircle" : "CheckCircle2"} size={20} className={`${isExpired ? 'text-gray-500' : 'text-success'} flex-shrink-0 mt-0.5`} />
          <div>
            <p className={`text-sm md:text-base font-semibold mb-1 ${isExpired ? 'text-gray-500' : 'text-success'}`}>
              Application Status: {isExpired ? 'Closed' : 'Open'}
            </p>
            <p className="text-xs md:text-sm text-foreground/70">
              {isExpired ? 'The deadline for this opportunity has passed.' : 'Applications are currently being accepted. Don\'t miss this opportunity!'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default KeyInformation;