import React from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const OpportunityHero = ({ opportunity, onSave, onShare, onApply, isSaved, isLiked, onLike }) => {
  const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;
  const daysUntilDeadline = opportunity?.daysLeft;

  const getDeadlineBadgeClass = (daysLeft) => {
    if (isExpired) return 'deadline-badge expired bg-gray-500/20 text-gray-500 border-gray-500/20';
    if (daysLeft === null) return 'deadline-badge safe';
    if (daysLeft <= 7) return 'deadline-badge urgent';
    if (daysLeft <= 14) return 'deadline-badge warning';
    return 'deadline-badge safe';
  };

  return (
    <div className="relative bg-gradient-to-br from-primary/5 via-secondary/5 to-accent/5 overflow-hidden">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-0 right-0 w-96 h-96 bg-brand-blue rounded-full blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-96 h-96 bg-brand-purple rounded-full blur-3xl"></div>
      </div>
      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-8 md:py-12 lg:py-16">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 lg:gap-12 items-center">
          <div className="order-2 lg:order-1 space-y-4 md:space-y-6">
            <div className="flex flex-wrap items-center gap-2 md:gap-3">
              <span className={getDeadlineBadgeClass(daysUntilDeadline)}>
                <Icon name={isExpired ? "AlertCircle" : "Clock"} size={14} />
                {isExpired ? "Expired" : (daysUntilDeadline === null ? (opportunity?.deadline || "No Deadline") : `${daysUntilDeadline} days left`)}
              </span>
              {opportunity?.verified && (
                <span className={cn(
                  "inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium",
                  isExpired ? "bg-gray-400/20 text-gray-500 grayscale" : "bg-success text-success-foreground"
                )}>
                  <Icon name={isExpired ? "Shield" : "ShieldCheck"} size={14} />
                  Verified
                </span>
              )}
              <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium bg-muted text-muted-foreground">
                <Icon name="Tag" size={14} />
                {opportunity?.category}
              </span>
            </div>

            <h1 className="text-2xl md:text-3xl lg:text-4xl font-bold text-primary leading-tight">
              {opportunity?.title}
            </h1>

            <div className="flex flex-wrap items-center gap-3 md:gap-4 text-sm md:text-base text-muted-foreground">
              <div className="flex items-center gap-2">
                <Icon name="Building2" size={18} />
                <span>{opportunity?.organization}</span>
              </div>
              <div className="flex items-center gap-2">
                <Icon name="MapPin" size={18} />
                <span>{opportunity?.location}</span>
              </div>
              <div className="flex items-center gap-2">
                <Icon name="DollarSign" size={18} />
                <span>{opportunity?.funding}</span>
              </div>
            </div>

            <p className="text-sm md:text-base lg:text-lg text-foreground/80 leading-relaxed">
              {opportunity?.shortDescription}
            </p>

            <div className="flex flex-col sm:flex-row gap-3 md:gap-4 pt-4">
              <Button
                variant={isExpired ? "outline" : "default"}
                size="lg"
                iconName={isExpired ? "Lock" : "ExternalLink"}
                iconPosition="right"
                fullWidth
                onClick={isExpired ? null : onApply}
                disabled={isExpired}
                className={cn("sm:w-auto h-12", isExpired && "opacity-50 grayscale")}
              >
                {isExpired ? 'Application Closed' : 'Apply Now'}
              </Button>
              <Button
                variant="outline"
                size="lg"
                iconName={isSaved ? "BookmarkCheck" : "Bookmark"}
                iconPosition="left"
                onClick={isExpired ? null : onSave}
                disabled={isExpired}
                fullWidth
                className={cn("sm:w-auto h-12", isExpired && "opacity-50 grayscale cursor-not-allowed")}
                title={isExpired ? "Cannot save expired opportunity" : (isSaved ? "Saved" : "Save")}
              >
                {isSaved ? 'Saved' : 'Save'}
              </Button>
              <Button
                variant="outline"
                size="lg"
                iconName="Share2"
                iconPosition="left"
                onClick={isExpired ? null : onShare}
                disabled={isExpired}
                fullWidth
                className={cn("sm:w-auto h-12", isExpired && "opacity-50 grayscale cursor-not-allowed")}
                title={isExpired ? "Cannot share expired opportunity" : "Share"}
              >
                Share
              </Button>
            </div>

            <div className="flex items-center gap-4 md:gap-6 pt-2 md:pt-4 border-t border-border">
              <div className="flex items-center gap-2">
                <Icon name="Users" size={18} className="text-secondary" />
                <span className="text-xs md:text-sm text-muted-foreground">
                  {opportunity?.applicants} applied
                </span>
              </div>
              <div className="flex items-center gap-2">
                <Icon name="Eye" size={18} className="text-secondary" />
                <span className="text-xs md:text-sm text-muted-foreground">
                  {opportunity?.views} views
                </span>
              </div>
              <button
                onClick={isExpired ? null : onLike}
                disabled={isExpired}
                className={cn(
                  "flex items-center gap-2 transition-colors duration-300",
                  isLiked ? 'text-red-500' : 'text-muted-foreground hover:text-red-500',
                  isExpired && "opacity-50 grayscale cursor-not-allowed"
                )}
                title={isExpired ? "Cannot like expired opportunity" : (isLiked ? "Unlike this opportunity" : "Love this opportunity")}
              >
                <Icon name="Heart" size={18} fill={isLiked ? "currentColor" : "none"} />
                <span className="text-xs md:text-sm font-medium">
                  {opportunity?.likes_count || 0} Loves
                </span>
              </button>
            </div>
          </div>

          <div className="order-1 lg:order-2">
            <div className="relative rounded-2xl overflow-hidden shadow-elevated aspect-[4/3] lg:aspect-square">
              <Image
                src={opportunity?.image}
                alt={opportunity?.imageAlt}
                className={cn("w-full h-full object-cover", isExpired && "grayscale")}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-primary/60 via-transparent to-transparent"></div>
              <div className="absolute bottom-4 md:bottom-6 left-4 md:left-6 right-4 md:right-6">
                <div className="flex items-center gap-3 bg-card/90 backdrop-blur-sm rounded-lg p-3 md:p-4">
                  <Image
                    src={opportunity?.organizationLogo}
                    alt={opportunity?.organizationLogoAlt}
                    className={cn("w-10 h-10 md:w-12 md:h-12 rounded-lg object-contain bg-white p-1", isExpired && "grayscale")}
                  />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs md:text-sm font-semibold text-primary truncate">
                      {opportunity?.organization}
                    </p>
                    <p className="text-xs text-muted-foreground truncate">
                      {opportunity?.organizationType}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};


export default OpportunityHero;
