import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';

const DetailedDescription = ({ opportunity }) => {
  const [expandedSections, setExpandedSections] = useState({
    overview: true,
    benefits: false,
    requirements: false,
    process: false
  });

  const toggleSection = (section) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev?.[section]
    }));
  };

  const sections = [
    {
      id: 'overview',
      icon: 'FileText',
      title: 'Overview',
      content: opportunity?.detailedDescription
    },
    {
      id: 'benefits',
      icon: 'Gift',
      title: 'Benefits & Coverage',
      content: opportunity?.benefits,
      list: opportunity?.benefitsList
    },
    {
      id: 'requirements',
      icon: 'ClipboardCheck',
      title: 'Eligibility Requirements',
      content: opportunity?.requirementsDescription,
      list: opportunity?.requirementsList
    },
    {
      id: 'process',
      icon: 'Route',
      title: 'Application Process',
      content: opportunity?.processDescription,
      list: opportunity?.processList
    }
  ];

  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-secondary/10 flex items-center justify-center">
          <Icon name="BookOpen" size={20} className="text-secondary" />
        </div>
        <h2 className="text-xl md:text-2xl font-bold text-primary">Detailed Information</h2>
      </div>
      <div className="space-y-4">
        {sections?.map((section) => (
          <div
            key={section?.id}
            className="border-2 border-border rounded-xl overflow-hidden transition-all duration-300 hover:border-secondary/50"
          >
            <button
              onClick={() => toggleSection(section?.id)}
              className="w-full flex items-center justify-between p-4 md:p-5 bg-background hover:bg-muted/50 transition-colors duration-300"
            >
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                  <Icon name={section?.icon} size={18} className="text-primary" />
                </div>
                <h3 className="text-base md:text-lg font-semibold text-foreground text-left">
                  {section?.title}
                </h3>
              </div>
              <Icon
                name={expandedSections?.[section?.id] ? 'ChevronUp' : 'ChevronDown'}
                size={20}
                className="text-muted-foreground flex-shrink-0"
              />
            </button>

            {expandedSections?.[section?.id] && (
              <div className="p-4 md:p-6 bg-card border-t-2 border-border">
                <p className="text-sm md:text-base text-foreground/80 leading-relaxed mb-4 whitespace-pre-line">
                  {section?.content}
                </p>
                {section?.list && section?.list?.length > 0 && (
                  <ul className="space-y-3">
                    {section?.list?.map((item, index) => (
                      <li key={index} className="flex items-start gap-3">
                        <Icon
                          name="CheckCircle2"
                          size={18}
                          className="text-success flex-shrink-0 mt-0.5"
                        />
                        <span className="text-sm md:text-base text-foreground/80">{item}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default DetailedDescription;