import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';

const ApplicationChecklist = ({ checklist }) => {
  const [completedItems, setCompletedItems] = useState([]);

  const toggleItem = (itemId) => {
    setCompletedItems(prev =>
      prev?.includes(itemId)
        ? prev?.filter(id => id !== itemId)
        : [...prev, itemId]
    );
  };

  const progress = (completedItems?.length / checklist?.length) * 100;

  return (
    <div className="bg-card rounded-2xl p-6 md:p-8 shadow-card">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg bg-accent/10 flex items-center justify-center">
          <Icon name="ListChecks" size={20} className="text-accent" />
        </div>
        <div className="flex-1">
          <h2 className="text-xl md:text-2xl font-bold text-primary">Application Checklist</h2>
          <p className="text-xs md:text-sm text-muted-foreground mt-1">
            Track your application progress
          </p>
        </div>
      </div>
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-foreground">
            {completedItems?.length} of {checklist?.length} completed
          </span>
          <span className="text-sm font-semibold text-primary">{Math.round(progress)}%</span>
        </div>
        <div className="w-full h-3 bg-muted rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-success to-brand-blue transition-all duration-500"
            style={{ width: `${progress}%` }}
          ></div>
        </div>
      </div>
      <div className="space-y-3">
        {checklist?.map((item) => {
          const isCompleted = completedItems?.includes(item?.id);
          return (
            <div
              key={item?.id}
              className={`p-4 md:p-5 rounded-xl border-2 transition-all duration-300 ${isCompleted
                ? 'border-success bg-success/5' : 'border-border bg-background hover:border-secondary/50'
                }`}
            >
              <div className="flex items-start gap-3">
                <Checkbox
                  checked={isCompleted}
                  onChange={() => toggleItem(item?.id)}
                  className="mt-1"
                />
                <div className="flex-1 min-w-0">
                  <h3
                    className={`text-sm md:text-base font-semibold mb-1 ${isCompleted ? 'text-success line-through' : 'text-foreground'
                      }`}
                  >
                    {item?.title}
                  </h3>
                  <p className="text-xs md:text-sm text-muted-foreground">{item?.description}</p>
                  {item?.tip && (
                    <div className="flex items-start gap-2 mt-2 p-2 md:p-3 rounded-lg bg-muted/50">
                      <Icon name="Lightbulb" size={14} className="text-accent flex-shrink-0 mt-0.5" />
                      <p className="text-xs text-foreground/70">{item?.tip}</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ApplicationChecklist;